use crate::Color;
use crate::PaletteDefinition;
use serde::Deserialize;
use serde::Deserializer;
use serde::Serialize;
use serde::Serializer;
use std::borrow::Borrow;
use std::collections::HashMap;
use std::collections::hash_map;
use std::hash::Hash;

/// A set of [`Color`]s keyed by their semantic names.
///
/// `N` is the palette definition - the type that determines which
/// color names exist. Two flavors:
///
/// - **Enum keys (type-safe)**: a fieldless enum implementing
///   [`PaletteDefinition`] (generated by
///   [`crate::palette_definition!`]) makes every lookup
///   type-checked and enables completeness checks via
///   [`Palette::missing`] and [`Palette::is_complete`].
/// - **Dynamic keys**: [`crate::NamedColor`] keeps the vocabulary
///   open for names not known at compile time.
///
/// Palette-level metadata that is not a color (textures, layout
/// flags, ...) stays in the consumer struct wrapping the `Palette`.
///
/// ```
/// use smearor_commons_color::Color;
/// use smearor_commons_color::Palette;
/// use smearor_commons_color::palette_definition;
///
/// palette_definition! {
///     /// Square colors of a board theme.
///     pub enum BoardSlot {
///         /// Light squares.
///         Light => "light",
///         /// Dark squares.
///         Dark => "dark"
///     }
/// }
///
/// let mut palette = Palette::<BoardSlot, f64>::new();
/// palette.insert(BoardSlot::Light, Color::<f64>::new(0.93, 0.83, 0.62));
/// assert_eq!(palette.get(&BoardSlot::Light), Some(&Color::<f64>::new(0.93, 0.83, 0.62)));
/// assert_eq!(palette.missing(), vec![BoardSlot::Dark]);
/// ```
#[derive(Debug, Clone)]
pub struct Palette<N, T> {
    /// Colors keyed by their semantic name.
    colors: HashMap<N, Color<T>>,
}

impl<N, T> Palette<N, T> {
    /// Creates an empty palette.
    pub fn new() -> Self {
        Self { colors: HashMap::new() }
    }

    /// The number of colors in the palette.
    pub fn len(&self) -> usize {
        self.colors.len()
    }

    /// `true` when the palette holds no colors.
    pub fn is_empty(&self) -> bool {
        self.colors.is_empty()
    }

    /// Iterates over all `(name, color)` pairs in arbitrary order.
    pub fn iter(&self) -> impl Iterator<Item = (&N, &Color<T>)> {
        self.colors.iter()
    }

    /// Returns a palette with every color transformed by `f` (e.g.
    /// channel conversion `Palette<N, f64>` -> `Palette<N, f32>`).
    pub fn map_colors<U>(&self, f: impl Fn(Color<T>) -> Color<U>) -> Palette<N, U>
    where
        N: Clone + Eq + Hash,
        T: Copy,
    {
        Palette {
            colors: self.colors.iter().map(|(name, color)| (name.clone(), f(*color))).collect(),
        }
    }
}

impl<N: Eq + Hash, T> Palette<N, T> {
    /// `true` when a color is registered under `name`.
    pub fn contains<Q>(&self, name: &Q) -> bool
    where
        N: Borrow<Q>,
        Q: Eq + Hash + ?Sized,
    {
        self.colors.contains_key(name)
    }

    /// The color registered under `name`, or `None`.
    ///
    /// Accepts either the key type (`&BoardSlot::Light`) or - for
    /// [`crate::NamedColor`] keys - a plain `&str` (`"light"`).
    pub fn get<Q>(&self, name: &Q) -> Option<&Color<T>>
    where
        N: Borrow<Q>,
        Q: Eq + Hash + ?Sized,
    {
        self.colors.get(name)
    }

    /// The color registered under `name`, or `fallback` when absent.
    pub fn get_or<Q>(&self, name: &Q, fallback: Color<T>) -> Color<T>
    where
        N: Borrow<Q>,
        Q: Eq + Hash + ?Sized,
        T: Clone,
    {
        self.colors.get(name).cloned().unwrap_or(fallback)
    }

    /// Registers `color` under `name`, returning the replaced color.
    pub fn insert(&mut self, name: impl Into<N>, color: Color<T>) -> Option<Color<T>> {
        self.colors.insert(name.into(), color)
    }

    /// Removes the color registered under `name`, returning it.
    pub fn remove<Q>(&mut self, name: &Q) -> Option<Color<T>>
    where
        N: Borrow<Q>,
        Q: Eq + Hash + ?Sized,
    {
        self.colors.remove(name)
    }
}

/// Methods available when the key type enumerates its vocabulary.
impl<N: PaletteDefinition, T> Palette<N, T> {
    /// The declared slots that have no color registered, in
    /// declaration order.
    pub fn missing(&self) -> Vec<N> {
        N::slots().iter().filter(|slot| !self.colors.contains_key(*slot)).copied().collect()
    }

    /// `true` when every declared slot carries a color.
    pub fn is_complete(&self) -> bool {
        N::slots().iter().all(|slot| self.colors.contains_key(slot))
    }

    /// Iterates all declared slots in declaration order, paired
    /// with their color (`None` for unfilled slots).
    pub fn ordered(&self) -> impl Iterator<Item = (N, Option<&Color<T>>)> {
        N::slots().iter().copied().map(|slot| (slot, self.colors.get(&slot)))
    }
}

/// An empty palette - no bound on `N` or `T` required.
impl<N, T> Default for Palette<N, T> {
    fn default() -> Self {
        Self::new()
    }
}

/// Palettes compare by their `(name, color)` pairs.
impl<N, T> PartialEq for Palette<N, T>
where
    N: Eq + Hash,
    T: PartialEq,
{
    fn eq(&self, other: &Self) -> bool {
        self.colors == other.colors
    }
}

impl<N, T> Eq for Palette<N, T>
where
    N: Eq + Hash,
    T: Eq,
{
}

/// Collecting `(name, color)` pairs - later duplicates win.
impl<N: Eq + Hash, T> FromIterator<(N, Color<T>)> for Palette<N, T> {
    fn from_iter<I: IntoIterator<Item = (N, Color<T>)>>(iter: I) -> Self {
        Self {
            colors: HashMap::from_iter(iter),
        }
    }
}

impl<N: Eq + Hash, T> Extend<(N, Color<T>)> for Palette<N, T> {
    fn extend<I: IntoIterator<Item = (N, Color<T>)>>(&mut self, iter: I) {
        self.colors.extend(iter);
    }
}

impl<'a, N, T> IntoIterator for &'a Palette<N, T> {
    type Item = (&'a N, &'a Color<T>);
    type IntoIter = hash_map::Iter<'a, N, Color<T>>;

    fn into_iter(self) -> Self::IntoIter {
        self.colors.iter()
    }
}

/// The wire format is a map `{ "name": "#rrggbb(aa)" }` - enum keys
/// serialize as their variant name, [`crate::NamedColor`] keys as the
/// name itself.
impl<N, T> Serialize for Palette<N, T>
where
    N: Eq + Hash + Serialize,
    Color<T>: Serialize,
{
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        self.colors.serialize(serializer)
    }
}

impl<'de, N, T> Deserialize<'de> for Palette<N, T>
where
    N: Eq + Hash + Deserialize<'de>,
    Color<T>: Deserialize<'de>,
{
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        Ok(Self {
            colors: HashMap::deserialize(deserializer)?,
        })
    }
}

/// Builds a [`Palette`] from `name => color` pairs.
///
/// Names go through `Into`, so enum variants can be used directly and
/// [`crate::NamedColor`] keys can be written as plain `&str`. For a
/// `const`-evaluable variant see [`crate::static_palette!`].
///
/// ```
/// use smearor_commons_color::Color;
/// use smearor_commons_color::NamedColor;
/// use smearor_commons_color::Palette;
/// use smearor_commons_color::palette;
///
/// let palette: Palette<NamedColor, f64> = palette! {
///     "light" => Color::<f64>::new(0.93, 0.83, 0.62),
///     "dark" => Color::<f64>::new(0.45, 0.30, 0.18),
/// };
/// assert_eq!(palette.get("light"), Some(&Color::<f64>::new(0.93, 0.83, 0.62)));
/// ```
#[macro_export]
macro_rules! palette {
    ($($name:expr => $color:expr),* $(,)?) => {
        $crate::Palette::from_iter([$(($name.into(), $color)),*])
    };
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::NamedColor;
    use crate::palette_definition;

    const LIGHT: NamedColor = NamedColor::new("light");
    const DARK: NamedColor = NamedColor::new("dark");
    const FRAME: NamedColor = NamedColor::new("frame");

    palette_definition! {
        /// Colors of a chess board theme.
        pub enum BoardSlot {
            /// Light squares.
            Light => "light",
            /// Dark squares.
            Dark => "dark",
            /// Frame around the board.
            Frame => "frame"
        }
    }

    fn board_palette() -> Palette<NamedColor, f64> {
        let mut palette = Palette::new();
        palette.insert(LIGHT.clone(), Color::<f64>::new(0.93, 0.83, 0.62));
        palette.insert("dark", Color::<f64>::new(0.45, 0.30, 0.18));
        palette
    }

    fn slot_palette() -> Palette<BoardSlot, f64> {
        let mut palette = Palette::new();
        palette.insert(BoardSlot::Light, Color::<f64>::new(0.93, 0.83, 0.62));
        palette.insert(BoardSlot::Dark, Color::<f64>::new(0.45, 0.30, 0.18));
        palette
    }

    #[test]
    fn insert_and_get_by_name() {
        let palette = board_palette();
        assert_eq!(palette.get("light"), Some(&Color::<f64>::new(0.93, 0.83, 0.62)));
        assert_eq!(palette.get(&LIGHT), Some(&Color::<f64>::new(0.93, 0.83, 0.62)));
        assert_eq!(palette.len(), 2);
        assert!(!palette.is_empty());
    }

    #[test]
    fn missing_name_returns_none() {
        let palette = board_palette();
        assert_eq!(palette.get("frame"), None);
        assert!(!palette.contains(&FRAME));
    }

    #[test]
    fn insert_replaces_and_returns_previous() {
        let mut palette = board_palette();
        let previous = palette.insert("light", Color::<f64>::WHITE);
        assert_eq!(previous, Some(Color::<f64>::new(0.93, 0.83, 0.62)));
        assert_eq!(palette.get("light"), Some(&Color::<f64>::WHITE));
    }

    #[test]
    fn get_or_returns_fallback_for_missing_name() {
        let palette = board_palette();
        assert_eq!(palette.get_or("frame", Color::<f64>::BLACK), Color::<f64>::BLACK);
        assert_eq!(palette.get_or("dark", Color::<f64>::BLACK), Color::<f64>::new(0.45, 0.30, 0.18));
    }

    #[test]
    fn remove_returns_the_color() {
        let mut palette = board_palette();
        assert_eq!(palette.remove("light"), Some(Color::<f64>::new(0.93, 0.83, 0.62)));
        assert_eq!(palette.remove("light"), None);
        assert_eq!(palette.len(), 1);
    }

    #[test]
    fn from_iter_collects_pairs() {
        let palette: Palette<NamedColor, f64> = [
            (LIGHT.clone(), Color::<f64>::new(0.9, 0.8, 0.7)),
            (DARK.clone(), Color::<f64>::new(0.1, 0.2, 0.3)),
        ]
        .into_iter()
        .collect();
        assert_eq!(palette.len(), 2);
        assert!(palette.contains("light"));
    }

    #[test]
    fn iter_yields_all_pairs() {
        let palette = board_palette();
        let names: Vec<&str> = palette.iter().map(|(name, _)| name.as_str()).collect();
        assert_eq!(names.len(), 2);
        assert!(names.contains(&"light"));
        assert!(names.contains(&"dark"));
    }

    #[test]
    fn map_colors_converts_channel_type() {
        let palette = slot_palette();
        let converted: Palette<BoardSlot, f32> = palette.map_colors(|color| color.into());
        assert_eq!(converted.get(&BoardSlot::Dark), Some(&Color::<f32>::new(0.45, 0.30, 0.18)));
    }

    #[test]
    fn typed_palette_get_is_type_checked() {
        let palette = slot_palette();
        assert_eq!(palette.get(&BoardSlot::Light), Some(&Color::<f64>::new(0.93, 0.83, 0.62)));
        assert!(palette.contains(&BoardSlot::Dark));
        assert!(palette.get(&BoardSlot::Frame).is_none());
    }

    #[test]
    fn missing_reports_unfilled_slots_in_declaration_order() {
        let palette = slot_palette();
        assert_eq!(palette.missing(), vec![BoardSlot::Frame]);
        assert!(!palette.is_complete());
        let mut palette = palette;
        palette.insert(BoardSlot::Frame, Color::<f64>::BLACK);
        assert!(palette.missing().is_empty());
        assert!(palette.is_complete());
    }

    #[test]
    fn ordered_iterates_declaration_order() {
        let palette = slot_palette();
        let slots: Vec<BoardSlot> = palette.ordered().map(|(slot, _)| slot).collect();
        assert_eq!(slots, vec![BoardSlot::Light, BoardSlot::Dark, BoardSlot::Frame]);
        let light = palette.ordered().next().map(|(_, color)| color);
        assert_eq!(light, Some(Some(&Color::<f64>::new(0.93, 0.83, 0.62))));
    }

    #[test]
    fn serde_round_trip_named_colors() {
        // Colors that survive the `#rrggbb` wire format exactly.
        let mut palette = Palette::<NamedColor, f64>::new();
        palette.insert("light", "#edd49e".parse::<Color<f64>>().unwrap());
        palette.insert("dark", "#734d2e".parse::<Color<f64>>().unwrap());
        let json = serde_json::to_string(&palette).unwrap();
        let parsed: Palette<NamedColor, f64> = serde_json::from_str(&json).unwrap();
        assert_eq!(parsed, palette);
    }

    #[test]
    fn palette_macro_builds_named_color_palette() {
        let palette: Palette<NamedColor, f64> = palette! {
            "light" => Color::<f64>::new(0.93, 0.83, 0.62),
            "dark" => Color::<f64>::new(0.45, 0.30, 0.18),
        };
        assert_eq!(palette.get("light"), Some(&Color::<f64>::new(0.93, 0.83, 0.62)));
        assert_eq!(palette.len(), 2);
    }

    #[test]
    fn palette_macro_builds_enum_palette() {
        let palette: Palette<BoardSlot, f64> = palette! {
            BoardSlot::Light => Color::<f64>::new(0.93, 0.83, 0.62),
            BoardSlot::Dark => Color::<f64>::new(0.45, 0.30, 0.18),
        };
        assert_eq!(palette.get(&BoardSlot::Dark), Some(&Color::<f64>::new(0.45, 0.30, 0.18)));
        assert_eq!(palette.missing(), vec![BoardSlot::Frame]);
    }

    #[test]
    fn serde_round_trip_enum_keys() {
        // Enum keys serialize as their variant name.
        let mut palette = Palette::<BoardSlot, f64>::new();
        palette.insert(BoardSlot::Light, "#edd49e".parse::<Color<f64>>().unwrap());
        let json = serde_json::to_string(&palette).unwrap();
        assert_eq!(json, "{\"Light\":\"#edd49e\"}");
        let parsed: Palette<BoardSlot, f64> = serde_json::from_str(&json).unwrap();
        assert_eq!(parsed, palette);
    }
}
